WITH parsed AS (SELECT id, created_at, items, ship_to, COALESCE(attributes['utm_source'], 'unknown') AS utm_source_or_default, AGGREGATE(items, 0D, (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS basket_amount, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines FROM carts) SELECT CASE WHEN bulk_lines >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END AS bulk_lines_tier, MIN(created_at) AS started_at, ROUND(AVG(bulk_lines), 2) AS avg_bulk_lines FROM parsed GROUP BY CASE WHEN bulk_lines >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END
